function createBaseVerifyAuditResponse(): VerifyAuditResponse {
  return { outcome: "", tamperedSeq: 0, tombstoneCount: 0 };
}

export const VerifyAuditResponse: MessageFns<VerifyAuditResponse> = {
  encode(message: VerifyAuditResponse, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.outcome !== "") {
      writer.uint32(10).string(message.outcome);
    }
    if (message.tamperedSeq !== 0) {
      writer.uint32(16).int64(message.tamperedSeq);
    }
    if (message.tombstoneCount !== 0) {
      writer.uint32(24).int64(message.tombstoneCount);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): VerifyAuditResponse {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const previousRecursionDepth = (reader as any).__tsProtoDecodeDepth ?? 0;
    if (previousRecursionDepth >= 100) {
      throw new globalThis.Error("protobuf decode recursion limit exceeded");
    }
    (reader as any).__tsProtoDecodeDepth = previousRecursionDepth + 1;
    try {
      const end = length === undefined ? reader.len : reader.pos + length;
      const message = createBaseVerifyAuditResponse();
      while (reader.pos < end) {
        const tag = reader.uint32();
        switch (tag >>> 3) {
          case 1: {
            if (tag !== 10) {
              break;
            }

            message.outcome = reader.string();
            continue;
          }
          case 2: {
            if (tag !== 16) {
              break;
            }

            message.tamperedSeq = longToNumber(reader.int64());
            continue;
          }
          case 3: {
            if (tag !== 24) {
              break;
            }

            message.tombstoneCount = longToNumber(reader.int64());
            continue;
          }
        }
        if ((tag & 7) === 4 || tag === 0) {
          break;
        }
        reader.skip(tag & 7);
      }
      return message;
    } finally {
      (reader as any).__tsProtoDecodeDepth = previousRecursionDepth;
    }
  },

  fromJSON(object: any): VerifyAuditResponse {
    return {
      outcome: isSet(object.outcome) ? globalThis.String(object.outcome) : "",
      tamperedSeq: isSet(object.tamperedSeq)
        ? globalThis.Number(object.tamperedSeq)
        : isSet(object.tampered_seq)
        ? globalThis.Number(object.tampered_seq)
        : 0,
      tombstoneCount: isSet(object.tombstoneCount)
        ? globalThis.Number(object.tombstoneCount)
        : isSet(object.tombstone_count)
        ? globalThis.Number(object.tombstone_count)
        : 0,
    };
  },

  toJSON(message: VerifyAuditResponse): unknown {
    const obj: any = {};
    if (message.outcome !== "") {
      obj.outcome = message.outcome;
    }
    if (message.tamperedSeq !== 0) {
      obj.tamperedSeq = Math.round(message.tamperedSeq);
    }
    if (message.tombstoneCount !== 0) {
      obj.tombstoneCount = Math.round(message.tombstoneCount);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<VerifyAuditResponse>, I>>(base?: I): VerifyAuditResponse {
    return VerifyAuditResponse.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<VerifyAuditResponse>, I>>(object: I): VerifyAuditResponse {
    const message = createBaseVerifyAuditResponse();
    message.outcome = object.outcome ?? "";
    message.tamperedSeq = object.tamperedSeq ?? 0;
    message.tombstoneCount = object.tombstoneCount ?? 0;
    return message;
  },
};

/**
 * Pki — internal-CA, pairing, and audit-chain RPCs. Lives in its own
 * service (and its own .proto) to keep mTLS-required RPCs isolated from
 * the looser admin surface. mTLS-required for every RPC.
 */
export type PkiDefinition = typeof PkiDefinition;
export const PkiDefinition = {
  name: "Pki",
  fullName: "borg.pki.v1.Pki",
  methods: {
    /**
     * Mints a fresh PAKE code, persists `sha256(code)` to `pairing_codes`, and
     * returns the plaintext code to the caller. The actual SPAKE2 exchange runs
     * over a separate plaintext bootstrap UDS socket — see borgd pairing module.
     */
    startPairing: {
      name: "StartPairing",
      requestType: StartPairingRequest as typeof StartPairingRequest,
      requestStream: false,
      responseType: StartPairingResponse as typeof StartPairingResponse,
      responseStream: false,
      options: {},
    },
    /**
     * Renew a client cert that's ≤14d from expiry. Requires the renewing
     * device's mTLS cert; the server verifies the active cert's fingerprint
     * matches `request.fingerprint` before issuing.
     */
    renewCert: {
      name: "RenewCert",
      requestType: RenewCertRequest as typeof RenewCertRequest,
      requestStream: false,
      responseType: RenewCertResponse as typeof RenewCertResponse,
      responseStream: false,
      options: {},
    },
    /** Revoke a paired device's fingerprint and add it to `revoked_fingerprints`. */
    revokeDevice: {
      name: "RevokeDevice",
      requestType: RevokeDeviceRequest as typeof RevokeDeviceRequest,
      requestStream: false,
      responseType: PkiEmpty as typeof PkiEmpty,
      responseStream: false,
      options: {},
    },
    listPairedDevices: {
      name: "ListPairedDevices",
      requestType: PkiEmpty as typeof PkiEmpty,
      requestStream: false,
      responseType: PairedDeviceList as typeof PairedDeviceList,
      responseStream: false,
      options: {},
    },
    /**
     * Replay the audit chain. Pure (no clock, no network) — deterministic
     * forensic verification.
     */
    verifyAuditChain: {
      name: "VerifyAuditChain",
      requestType: PkiEmpty as typeof PkiEmpty,
      requestStream: false,
      responseType: VerifyAuditResponse as typeof VerifyAuditResponse,
      responseStream: false,
      options: {},
    },
    /**
     * Inspect the calling device's cert lifecycle so the client can
     * self-trigger a `RenewCert` when its cert is within the 14-day renewal
     * window. Requires mTLS — the daemon answers based on the principal's
     * own active cert (request body intentionally empty).
     */
    getCertLifecycle: {
      name: "GetCertLifecycle",
      requestType: PkiEmpty as typeof PkiEmpty,
      requestStream: false,
      responseType: CertLifecycleResponse as typeof CertLifecycleResponse,
      responseStream: false,
      options: {},
    },
  },
} as const;

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I> = P extends Builtin ? P
  :
    & P
    & { [K in keyof P as Extract<K, keyof I>]: Exact<P[K], I[K & keyof I]> }
    & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function longToNumber(int64: { toString(): string }): number {
  const num = globalThis.Number(int64.toString());
  if (num > globalThis.Number.MAX_SAFE_INTEGER) {
    throw new globalThis.Error("Value is larger than Number.MAX_SAFE_INTEGER");
  }
  if (num < globalThis.Number.MIN_SAFE_INTEGER) {
    throw new globalThis.Error("Value is smaller than Number.MIN_SAFE_INTEGER");
  }
  return num;
}

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
